      # @option body [String] :redirectUrl When done, the result page links the browser here (the user clicks to leave Ampost), with the outcome in the query (https; http only for localhost).
      # @option body [String] :state Returned unchanged as `state` on `redirectUrl`.
      # @param idempotency_key [String, nil] Sent as `Idempotency-Key`; default: a new UUID.
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `ConnectRequestCreated`.
      def connect(body, **options)
        @client.request("POST", "/api/accounts/connect", body: body, idempotent: true, options: options)
