      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `ConnectRequest`.
      def get_connect_request(connect_request_id, **options)
        @client.request("GET", "/api/accounts/connect/#{path(connect_request_id)}", options: options)
      end
    end

