        @client.request("PATCH", "/api/platform-sets/#{path(platform_set_id)}", body: body, options: options)
      end

      # Delete a platform set
      #
      # Delete a platform set and revoke its active accounts. Its disconnected accounts and its posts are kept without a set; reconnect an account with accounts_connect and its accountId to put it in another set. Your last remaining set cannot be deleted (409 LAST_PLATFORM_SET). 409 PLATFORM_SET_IN_USE means an account was connected to the set during the delete: retry.
      #
      # MCP tool: `platform_sets_delete`. Key scope: `accounts:write`.
      #
      # `DELETE /api/platform-sets/{platformSetId}`
      #
      # @param platform_set_id [String]
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
