      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `QueuePreview`.
      def get_queue_slots(platform_set_id, count: nil, filter: nil, **options)
        @client.request("GET", "/api/platform-sets/#{path(platform_set_id)}/queue/slots", query: { "count" => count, "filter" => filter }, options: options)
      end
