      # @return [Ampost::Page] Items: `AnalyticsFollowers` hashes.
      def list_followers(from: nil, to: nil, platform: nil, platform_set_id: nil, account_id: nil, limit: nil, offset: nil, **options)
        @client.paginate("GET", "/api/analytics/followers", query: { "from" => from, "to" => to, "platform" => platform, "platformSetId" => platform_set_id, "accountId" => account_id, "limit" => limit, "offset" => offset }, options: options)
      end
