    # `webhooks` operations: `client.webhooks`.
    class Webhooks < Resource
      # List webhooks
      #
      # List your webhooks, oldest first. Secrets show only as `secretPreview`. Webhooks see every platform set, so keys restricted to some sets get 403 PLATFORM_SET_NOT_ALLOWED.
      #
      # MCP tool: `webhooks_list`. Key scope: `webhooks:write`.
      #
      # `GET /api/webhooks/endpoints`
      #
      # Returns one page; `each` walks every item across pages.
      #
      # @param limit [Integer, nil] Page size, 1-100. Default 20.
      # @param offset [Integer, nil] Number of items to skip. Default 0.
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Ampost::Page] Items: `Webhook` hashes.
      def list(limit: nil, offset: nil, **options)
        @client.paginate("GET", "/api/webhooks/endpoints", query: { "limit" => limit, "offset" => offset }, options: options)
      end

      # Create a webhook
      #
      # Send events to an https URL. Ampost POSTs each event as JSON, signed with the webhook's secret (`Ampost-Signature`), and retries a failed delivery 7 times (1 min, 5 min, 30 min, 2 h, 6 h, 12 h and 24 h). After 5 deliveries in a row fail all retries the webhook is turned off. At most 10 webhooks. The response is the only one with the full `secret`: store it now. Revoking the key or app that created the webhook turns it off. Events: post.scheduled, post.unscheduled, post.discarded, post.published, post.partial, post.failed, post.platform.published, post.platform.failed, post.platform.deleted, post.platform.edited, account.connected, account.disconnected, account.needs_reconnect, analytics.synced. Webhooks see every platform set, so keys restricted to some sets get 403 PLATFORM_SET_NOT_ALLOWED.
      #
      # MCP tool: `webhooks_create`. Key scope: `webhooks:write`.
      #
      # `POST /api/webhooks/endpoints`
      #
      # Sends an `Idempotency-Key`: yours (`idempotency_key:`), or a generated one kept across retries.
      #
      # @param body [Hash] The request body (`CreateWebhookRequest`), with the API's field names as keys.
      # @option body [String] :url Required. Public https URL that receives the events. Private, loopback, internal and Ampost's own hosts are rejected.
      # @option body [Array<String>] :events Required. Events to send to this URL
      # @option body [String, nil] :description Your note for this webhook, at most 200 characters
      # @param idempotency_key [String, nil] Sent as `Idempotency-Key`; default: a new UUID.
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `Webhook`.
      def create(body, **options)
        @client.request("POST", "/api/webhooks/endpoints", body: body, idempotent: true, options: options)
      end

      # Get a webhook
      #
      # Get one webhook with its status and failure count. The secret shows only as `secretPreview`. Webhooks see every platform set, so keys restricted to some sets get 403 PLATFORM_SET_NOT_ALLOWED.
      #
      # MCP tool: `webhooks_get`. Key scope: `webhooks:write`.
      #
      # `GET /api/webhooks/endpoints/{webhookId}`
      #
      # @param webhook_id [String]
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `Webhook`.
      def get(webhook_id, **options)
        @client.request("GET", "/api/webhooks/endpoints/#{path(webhook_id)}", options: options)
      end

      # Update a webhook
      #
      # Change a webhook's URL, events or description, turn it on or off, or rotate its secret (the response then has the new `secret`, the only time it is shown). While a webhook is off no events are queued for it. Turning it back on resets its failure count; events it missed are not sent, so resend the ones you need with webhooks_redeliver. A webhook turned off because its key or app was revoked (`disabledReason: "key_revoked"`) can only be turned on in the dashboard. Changing the URL or rotating the secret ties the webhook to the calling key or app.
      #
      # MCP tool: `webhooks_update`. Key scope: `webhooks:write`.
      #
      # `PATCH /api/webhooks/endpoints/{webhookId}`
      #
      # @param webhook_id [String]
      # @param body [Hash, nil] The request body (`UpdateWebhookRequest`), with the API's field names as keys.
      # @option body [String] :url Public https URL that receives the events. Private, loopback, internal and Ampost's own hosts are rejected.
      # @option body [Array<String>] :events Events to send to this URL
      # @option body [String, nil] :description Your note for this webhook, at most 200 characters
      # @option body [Boolean] :enabled Turn the webhook on or off. Turning it on clears `disabledReason` and the failure count.
      # @option body [Boolean] :rotateSecret True: replace the signing secret. The old one stops working at once.
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `Webhook`.
      def update(webhook_id, body = nil, **options)
