      end

      # Delete a webhook
      #
      # Delete a webhook and its delivery log. Pending deliveries are not sent.
      #
      # MCP tool: `webhooks_delete`. Key scope: `webhooks:write`.
      #
      # `DELETE /api/webhooks/endpoints/{webhookId}`
      #
      # @param webhook_id [String]
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `Deleted`.
      def delete(webhook_id, **options)
        @client.request("DELETE", "/api/webhooks/endpoints/#{path(webhook_id)}", options: options)
      end

      # Send a test event
      #
      # Send a signed `webhook.test` event to the webhook now, also when it is turned off, and return the delivery with your URL's response. One attempt, no retries.
      #
      # MCP tool: `webhooks_test`. Key scope: `webhooks:write`.
      #
      # `POST /api/webhooks/endpoints/{webhookId}/test`
      #
      # @param webhook_id [String]
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `WebhookDelivery`.
      def test(webhook_id, **options)
        @client.request("POST", "/api/webhooks/endpoints/#{path(webhook_id)}/test", options: options)
      end

      # List webhook deliveries
      #
      # The webhook's delivery log, newest first: each event sent, its status, attempts, and the last response code and body. Kept for 30 days.
      #
      # MCP tool: `webhooks_deliveries_list`. Key scope: `webhooks:write`.
      #
      # `GET /api/webhooks/endpoints/{webhookId}/deliveries`
      #
      # Returns one page; `each` walks every item across pages.
      #
      # @param webhook_id [String]
      # @param limit [Integer, nil] Page size, 1-100. Default 20.
      # @param offset [Integer, nil] Number of items to skip. Default 0.
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Ampost::Page] Items: `WebhookDelivery` hashes.
      def list_deliveries(webhook_id, limit: nil, offset: nil, **options)
        @client.paginate("GET", "/api/webhooks/endpoints/#{path(webhook_id)}/deliveries", query: { "limit" => limit, "offset" => offset }, options: options)
      end

      # Redeliver an event
      #
      # Send a past delivery's event again now, with the same event id and body, as a new delivery (one attempt, also when the webhook is turned off). Returns the new delivery with your URL's response.
      #
      # MCP tool: `webhooks_redeliver`. Key scope: `webhooks:write`.
      #
      # `POST /api/webhooks/endpoints/{webhookId}/deliveries/{deliveryId}/redeliver`
      #
      # @param webhook_id [String]
      # @param delivery_id [String]
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `WebhookDelivery`.
      def redeliver(webhook_id, delivery_id, **options)
        @client.request("POST", "/api/webhooks/endpoints/#{path(webhook_id)}/deliveries/#{path(delivery_id)}/redeliver", options: options)
      end
    end

    # `docs` operations: `client.docs`.
    class Docs < Resource
      # Search the docs
      #
      # Search the Ampost docs (`/docs`, `/docs/mcp` and `/llms-full.txt`) for a question such as "schedule a post to instagram". Returns the best matching sections, each with its title, a short excerpt and its URL. Any valid key may call it, and it is not counted toward the plan's 30-day API requests.
      #
      # MCP tool: `docs_search`. Key scope: none (any key).
      #
      # `GET /api/docs/search`
      #
      # @param query [String] What you want to know, in plain words, e.g. "schedule a post to instagram".
      # @param limit [Integer, nil] Number of sections, 1-20. Default 5.
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `DocsSearchResults`.
      def search(query:, limit: nil, **options)
        @client.request("GET", "/api/docs/search", query: { "query" => query, "limit" => limit }, options: options)
      end
    end

    # `feedback` operations: `client.feedback`.
    class Feedback < Resource
      # Report a bug or suggest a change
      #
      # Send the Ampost team a bug report or a suggestion. When an Ampost call fails in a way you can't explain or fix, report it with the `request` you sent (method, path or tool, body) and the `error` you got (status, code, message, `X-Request-Id`). Ampost adds the user's plan and connected accounts with their health. Fields named like secrets and Ampost keys in strings are removed; don't send credentials. Any valid key may call it, at most 10 reports an hour and 20 a day (5 a day with a screenshot); it is not counted toward the plan's 30-day API requests.
      #
      # MCP tool: `feedback_submit`. Key scope: none (any key).
      #
      # `POST /api/feedback`
      #
      # Sends an `Idempotency-Key`: yours (`idempotency_key:`), or a generated one kept across retries.
      #
      # @param body [Hash] The request body, with the API's field names as keys.
      # @option body [String] :kind Required. `bug` for something that went wrong, `suggestion` for a change you want
      # @option body [String] :message Required. What happened and what you expected, or what you want changed. At most 5000 characters.
      # @option body [String] :route The dashboard page, or the API path or MCP tool the report is about
      # @option body [Hash] :request The request that failed, as you sent it
      # @option body [Hash] :error The error Ampost answered
      # @option body [Array<Hash>] :recentRequests The dashboard's last API calls; the dashboard fills it in
      # @option body [String] :browser The browser's user agent; the dashboard fills it in
      # @option body [String] :screenshot Optional PNG or JPEG, base64 (a `data:` URL is fine). Ampost re-encodes it as JPEG within 1920 px; one still over 1 MB is refused. At most 5 a day.
      # @param idempotency_key [String, nil] Sent as `Idempotency-Key`; default: a new UUID.
      # @param options [Hash] `timeout:`, `max_retries:` and `extra_headers:` for this call.
      # @return [Hash] The `FeedbackReceipt`.
      def submit(body, **options)
        @client.request("POST", "/api/feedback", body: body, idempotent: true, options: options)
      end
    end

    # Every resource of the API, one reader per tag. Ampost::Client includes it.
    module Readers
      # @return [Ampost::Resources::Platforms]
      attr_reader :platforms

      # @return [Ampost::Resources::Posts]
      attr_reader :posts

      # @return [Ampost::Resources::Media, Ampost::MediaResource]
      attr_reader :media

      # @return [Ampost::Resources::Accounts]
      attr_reader :accounts

      # @return [Ampost::Resources::PlatformSets]
      attr_reader :platform_sets

      # @return [Ampost::Resources::Analytics]
      attr_reader :analytics

      # @return [Ampost::Resources::Webhooks]
      attr_reader :webhooks

      # @return [Ampost::Resources::Docs]
      attr_reader :docs

      # @return [Ampost::Resources::Feedback]
      attr_reader :feedback

      private

      def init_resources
        @platforms = Platforms.new(self)
        @posts = Posts.new(self)
        @media = Media.new(self)
        @accounts = Accounts.new(self)
        @platform_sets = PlatformSets.new(self)
        @analytics = Analytics.new(self)
        @webhooks = Webhooks.new(self)
        @docs = Docs.new(self)
        @feedback = Feedback.new(self)
      end
    end
  end

